using(var t=new Transaction(document,"Unique model type identifiers")){t.Start();foreach(var s in new FilteredElementCollector(document).WhereElementIsElementType().Where(s=>s.Name.StartsWith("LC ")||(s is FamilySymbol&&((FamilySymbol)s).FamilyName=="LC Rectangular Timber"))){var p=s.get_Parameter(BuiltInParameter.ALL_MODEL_TYPE_MARK);if(p!=null&&!p.IsReadOnly)p.Set("LC-"+s.Id.Value);}t.Commit();}document.Save();return new{warnings=document.GetWarnings().Select(w=>w.GetDescriptionText()).ToArray()};
